// core/deck/remote.hpp — what a REMOTE client (a phone, a desk on another computer) is sent in place of the
// window's meta: lib/phone.js clipMessage / remoteMeta / deskMeta / metaKey, ported. PURE.
// Checked against core/test/fixtures/deck/remote.json (generated by running lib/phone.js).
#pragma once
#include "../third_party/nlohmann/json.hpp"
#include <functional>
#include <set>
#include <string>

namespace deck { namespace core {

using json = nlohmann::json;

constexpr int kMsgCharsPerLine = 200;               // MSG_CHARS_PER_LINE
constexpr double kMetaKeepaliveMs = 20000;          // META_KEEPALIVE_MS
constexpr size_t kMaxBuffered = 4 * 1024 * 1024;    // MAX_BUFFERED

// The head of a message: its first `lines` non-blank lines, at most lines x 200 characters (UTF-16 units).
std::string clipMessage(const std::string& text, int lines);
// every tile's lastText clipped to the preview it feeds (a desk: the wider of the two previews)
json remoteMeta(const json& meta, bool desk);
// A desk's copy: `mirror` per tile is what THAT desk must render at — null when it drives (it shows the tile,
// the driver is not `desk`, no phone has it), else the pty's real size while it shows the tile.
json deskMeta(const json& meta, const std::set<std::string>& shown, bool hidden, const std::function<bool(const std::string&)>& phoneWatching);
// The same under the 2026-11-18 rules (the review branch's lib/phone.js deskMeta; fixtures: driverrule.json):
//   ownWindowsOnly  the remote-desk rule: a remote desk is told of no window on the deck's box holding a session
//                   (`inWindow` null on every tile)
//   claim           the driver as a claim: `mirror` is driverrule::remoteMirror (a remote desk is not a phone)
// Both false = the function above.
struct DeskRule { bool ownWindowsOnly = false; bool claim = false; };
json deskMeta(const json& meta, const std::set<std::string>& shown, bool hidden, const std::function<bool(const std::string&)>& phoneWatching, const DeskRule& rule);
// what makes two metas the same to a client: everything but the clock
std::string metaKey(const json& meta, const json& assets, const json& build);

}}  // namespace deck::core
